function getRelatedProjects(projectId, limit = 4) {
  const current = PROJECTS.find((p) => p.id === projectId);
  if (!current) return [];
  return PROJECTS.filter((p) => p.category === current.category && p.id !== projectId).slice(0, limit);
}

